<?php
require_once __DIR__ . '/includes/company_helpers.php';
$projectStatuses=['planned'=>'مخطط','in_progress'=>'قيد التنفيذ','on_hold'=>'متوقف مؤقتًا','completed'=>'مكتمل','cancelled'=>'ملغي'];
if(is_post()){
  require_csrf();$id=(int)input('id');$name=company_input('name',190);$type=company_enum(input('project_type'),['client','internal'],'client');
  $clientId=company_optional_id('client_id');$managerId=company_optional_id('manager_id');$status=company_enum(input('project_status'),array_keys($projectStatuses),'planned');
  $start=company_valid_date(company_input('start_date',10));$due=company_valid_date(company_input('due_date',10));$value=company_decimal('contract_value');$description=company_input('description',20000);
  $clientId=$type==='internal'?null:$clientId;
  $managerExists=!$managerId||db_fetch('SELECT id FROM company_employees WHERE id=?',[$managerId]);
  if($name===''||($type==='client'&&(!$clientId||!db_fetch('SELECT id FROM company_clients WHERE id=?',[$clientId])))||!$managerExists||$start===false||$due===false||$value===false||($start&&$due&&$due<$start)){
    company_flash_error('בדוק את שם المشروع, العميل المرتبط, התאריכים והميزانية. للمشروع الداخلي لا يلزم اختيار عميل.');
  }else{
    if($id>0){db_query('UPDATE company_projects SET name=?,project_type=?,client_id=?,manager_id=?,project_status=?,start_date=?,due_date=?,contract_value=?,description=? WHERE id=?',[$name,$type,$clientId,$managerId,$status,$start,$due,$value,$description?:null,$id]);company_activity('تعديل مشروع شركة',$name);flash('success','تم تحديث المشروع.');}
    else{db_query('INSERT INTO company_projects (name,project_type,client_id,manager_id,project_status,start_date,due_date,contract_value,description) VALUES (?,?,?,?,?,?,?,?,?)',[$name,$type,$clientId,$managerId,$status,$start,$due,$value,$description?:null]);company_activity('إضافة مشروع شركة',$name);flash('success','تم إضافة المشروع.');}
    redirect('company-projects.php');
  }
}
$editId=filter_input(INPUT_GET,'edit',FILTER_VALIDATE_INT)?:0;$project=$editId?db_fetch('SELECT * FROM company_projects WHERE id=?',[$editId]):null;
$clients=db_fetch_all('SELECT id,name,company_name FROM company_clients WHERE client_status=\'active\' ORDER BY name');$employees=db_fetch_all('SELECT id,full_name,job_title FROM company_employees WHERE employment_status<>\'inactive\' ORDER BY full_name');
$clientFilter=filter_input(INPUT_GET,'client',FILTER_VALIDATE_INT)?:0;
$sql="SELECT p.*,c.name client_name,e.full_name manager_name,COALESCE(t.income,0) project_income,COALESCE(t.costs,0) project_costs,COALESCE(w.payroll,0) project_payroll FROM company_projects p LEFT JOIN company_clients c ON c.id=p.client_id LEFT JOIN company_employees e ON e.id=p.manager_id LEFT JOIN (SELECT project_id,SUM(CASE WHEN transaction_kind='income' THEN amount ELSE 0 END) income,SUM(CASE WHEN transaction_kind IN ('expense','purchase') THEN amount ELSE 0 END) costs FROM company_transactions WHERE voided_at IS NULL GROUP BY project_id) t ON t.project_id=p.id LEFT JOIN (SELECT project_id,SUM(base_salary+allowances+employer_contributions) payroll FROM company_payroll GROUP BY project_id) w ON w.project_id=p.id";
$projects=db_fetch_all($sql.($clientFilter?' WHERE p.client_id=?':'')." ORDER BY FIELD(p.project_status,'in_progress','planned','on_hold','completed','cancelled'),p.due_date IS NULL,p.due_date,p.id DESC",$clientFilter?[$clientFilter]:[]);
$adminTitle='مشاريع الشركة';$adminSubtitle='مشاريع العملاء والمشاريع الداخلية';$adminActive='company_projects';require __DIR__.'/includes/header.php';
?>
<div class="page-head"><div><h1>مشاريع الشركة</h1><p class="sub">اربط مشاريع العملاء بملفاتهم، أو أنشئ مشروعًا داخليًا، وتابع المسؤول والمدة والقيمة والنتيجة المالية.</p></div><?php if($clientFilter): ?><div class="actions"><a class="btn btn-outline" href="company-projects.php">كل المشاريع</a></div><?php endif; ?></div>
<form method="post" action="company-projects.php<?php echo $project?'?edit='.(int)$project['id']:''; ?>" data-loading><?php echo csrf_field(); ?><input type="hidden" name="id" value="<?php echo (int)($project['id']??0); ?>"><div class="panel"><div class="panel-head"><h2><?php echo $project?'تعديل المشروع':'إضافة مشروع'; ?></h2></div><div class="panel-body"><div class="form-grid">
<div class="form-group"><label>اسم المشروع *</label><input class="form-control" name="name" maxlength="190" required value="<?php echo e($project['name']??''); ?>"></div>
<div class="form-group"><label>نوع المشروع</label><select class="form-control" name="project_type"><option value="client" <?php echo ($project['project_type']??'client')==='client'?'selected':''; ?>>مشروع عميل</option><option value="internal" <?php echo ($project['project_type']??'')==='internal'?'selected':''; ?>>مشروع داخلي للشركة</option></select></div>
<div class="form-group"><label>العميل</label><select class="form-control" name="client_id"><option value="">— لا يوجد (للمشروع الداخلي) —</option><?php foreach($clients as $c): ?><option value="<?php echo (int)$c['id']; ?>" <?php echo (int)($project['client_id']??$clientFilter)===(int)$c['id']?'selected':''; ?>><?php echo e($c['name'].($c['company_name']?' — '.$c['company_name']:'')); ?></option><?php endforeach; ?></select><span class="hint">يجب اختيار عميل عند تحديد نوع «مشروع عميل».</span></div>
<div class="form-group"><label>مدير المشروع</label><select class="form-control" name="manager_id"><option value="">— غير محدد —</option><?php foreach($employees as $eRow): ?><option value="<?php echo (int)$eRow['id']; ?>" <?php echo (int)($project['manager_id']??0)===(int)$eRow['id']?'selected':''; ?>><?php echo e($eRow['full_name'].' — '.$eRow['job_title']); ?></option><?php endforeach; ?></select></div>
<div class="form-group"><label>الحالة</label><select class="form-control" name="project_status"><?php foreach($projectStatuses as $key=>$label): ?><option value="<?php echo e($key); ?>" <?php echo ($project['project_status']??'planned')===$key?'selected':''; ?>><?php echo e($label); ?></option><?php endforeach; ?></select></div>
<div class="form-group"><label>قيمة التعاقد (ج.م)</label><input class="form-control ltr" type="number" min="0" step="0.01" name="contract_value" value="<?php echo e($project['contract_value']??'0'); ?>"></div>
<div class="form-group"><label>تاريخ البداية</label><input class="form-control ltr" type="date" name="start_date" value="<?php echo e($project['start_date']??''); ?>"></div><div class="form-group"><label>تاريخ التسليم المتوقع</label><input class="form-control ltr" type="date" name="due_date" value="<?php echo e($project['due_date']??''); ?>"></div>
<div class="form-group full"><label>التفاصيل ونطاق العمل والمراحل</label><textarea class="form-control" name="description" rows="4" maxlength="20000"><?php echo e($project['description']??''); ?></textarea></div>
</div></div><div class="form-actions"><a class="btn btn-outline" href="company-projects.php">إلغاء</a><div class="right"><button class="btn btn-primary" type="submit">حفظ المشروع</button></div></div></div></form>
<div class="panel"><div class="panel-head"><h2><?php echo $clientFilter?'مشاريع العميل المحدد':'المشاريع'; ?> (<?php echo count($projects); ?>)</h2></div><div class="panel-body p0"><div class="table-wrap"><table class="table"><thead><tr><th>المشروع</th><th>النوع والعميل</th><th>المسؤول والمدة</th><th>الحالة</th><th>قيمة التعاقد</th><th>الإيرادات / التكلفة</th><th></th></tr></thead><tbody>
<?php foreach($projects as $row): $projectMargin=(float)$row['project_income']-(float)$row['project_costs']-(float)$row['project_payroll']; ?><tr><td><div class="cell-title"><?php echo e($row['name']); ?></div><div class="cell-sub"><?php echo e(mb_strimwidth((string)$row['description'],0,110,'…','UTF-8')); ?></div></td><td><?php echo $row['project_type']==='internal'?'داخلي':'عميل'; ?><div class="cell-sub"><?php echo e($row['client_name']??'—'); ?></div></td><td><?php echo e($row['manager_name']?:'غير محدد'); ?><div class="cell-sub"><?php echo e(($row['start_date']?:'—').' ← '.($row['due_date']?:'—')); ?></div></td><td><?php echo e($projectStatuses[$row['project_status']]); ?></td><td><?php echo e(company_money($row['contract_value'])); ?></td><td><span class="cell-title"><?php echo e(company_money($row['project_income'])); ?></span><div class="cell-sub">تكاليف: <?php echo e(company_money($row['project_costs'])); ?> · عمالة: <?php echo e(company_money($row['project_payroll'])); ?> · هامش: <?php echo e(company_money($projectMargin)); ?></div></td><td><a class="btn btn-outline btn-sm" href="company-projects.php?edit=<?php echo (int)$row['id']; ?>">تعديل</a> <a class="btn btn-outline btn-sm" href="finance.php?project=<?php echo (int)$row['id']; ?>">الحركات</a></td></tr><?php endforeach; ?>
<?php if(!$projects): ?><tr><td colspan="7" class="muted">لا توجد مشاريع بهذا الاختيار.</td></tr><?php endif; ?></tbody></table></div></div></div>
<?php require __DIR__.'/includes/footer.php'; ?>
